  ""code"": ""import sys

# Function to handle exceptions and convert string to number
def string_to_number(user_input, data_type):
    try:
        if data_type == ""integer"":
            result = int(user_input)
            print(f""Converted number: {result}"")
        elif data_type == ""float"":
            result = float(user_input)
            print(f""Converted number: {result}"")
    except ValueError:
        if not user_input.isascii():
            print(""Error: Input contains non-ASCII characters."")
        elif not user_input:
            print(""Error: Input string is empty."")
        else:
            print(""Error: Input string is not a valid number."")
    except OverflowError:
        print(""Error: Input number is out of range for the selected data type."")

# Call the function with user input and data type
string_to_number(input(""Enter a number: ""), ""integer"")""
